import {emptySemantic,validateSemantic} from './semantic.js';
export function random(seed){let s=seed>>>0;return()=>{s=(Math.imul(s,1664525)+1013904223)>>>0;return s/4294967296;};}
function shuffle(list,rng){const a=[...list];for(let i=a.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
export function candidates(board,index){if(board[index])return [];const row=Math.floor(index/9),col=index%9,used=new Set();for(let k=0;k<9;k++){used.add(board[row*9+k]);used.add(board[k*9+col]);used.add(board[(Math.floor(row/3)*3+Math.floor(k/3))*9+Math.floor(col/3)*3+k%3]);}return [1,2,3,4,5,6,7,8,9].filter(n=>!used.has(n));}
export function sudokuConflicts(board){const bad=new Set();for(let i=0;i<81;i++)if(board[i])for(let j=i+1;j<81;j++)if(board[i]===board[j]&&(Math.floor(i/9)===Math.floor(j/9)||i%9===j%9||(Math.floor(i/27)===Math.floor(j/27)&&Math.floor(i%9/3)===Math.floor(j%9/3)))){bad.add(i);bad.add(j);}return bad;}
export function solutionCount(board,limit=2){if(sudokuConflicts(board).size)return 0;const a=[...board];let count=0;function solve(){if(count>=limit)return;let chosen=-1,opts=[];for(let i=0;i<81;i++)if(!a[i]){const c=candidates(a,i);if(!c.length)return;if(chosen===-1||c.length<opts.length){chosen=i;opts=c;if(c.length===1)break;}}if(chosen<0){count++;return;}for(const n of opts){a[chosen]=n;solve();a[chosen]=0;if(count>=limit)break;}}solve();return count;}
export function createSudoku(seed,level='gentle'){const rng=random(seed),bands=shuffle([0,1,2],rng),stacks=shuffle([0,1,2],rng),rows=bands.flatMap(b=>shuffle([0,1,2],rng).map(i=>b*3+i)),cols=stacks.flatMap(b=>shuffle([0,1,2],rng).map(i=>b*3+i)),digits=shuffle([1,2,3,4,5,6,7,8,9],rng);const solution=rows.flatMap(r=>cols.map(c=>digits[(r*3+Math.floor(r/3)+c)%9]));const givens=[...solution],target=level==='gentle'?44:34;let left=81;for(const i of shuffle(Array.from({length:81},(_,i)=>i),rng)){if(left<=target)break;const old=givens[i];givens[i]=0;if(solutionCount(givens)===1)left--;else givens[i]=old;}return {id:'s'+seed,seed,level,givens,solution,board:[...givens],notes:Array.from({length:81},()=>[]),selected:-1,noteMode:false,hints:0,undo:[],complete:false};}
export function oneLetter(a,b){return a.length===b.length&&[...a].filter((c,i)=>c!==b[i]).length===1;}
export function makeWordGraph(words){const buckets=new Map();for(const w of words)for(let i=0;i<w.length;i++){const key=w.slice(0,i)+'*'+w.slice(i+1);if(!buckets.has(key))buckets.set(key,[]);buckets.get(key).push(w);}return {words:new Set(words),neighbors(w){const out=new Set();for(let i=0;i<w.length;i++)for(const next of buckets.get(w.slice(0,i)+'*'+w.slice(i+1))||[])if(next!==w)out.add(next);return [...out];}};}
export function shortestPath(graph,start,target){if(start===target)return [start];const q=[start],parent=new Map([[start,null]]);for(let p=0;p<q.length;p++){for(const next of graph.neighbors(q[p])){if(parent.has(next))continue;parent.set(next,q[p]);if(next===target){const path=[next];while(parent.get(path[0])!==null)path.unshift(parent.get(path[0]));return path;}q.push(next);}}return null;}
export function createLadder(seed,graph){const rng=random(seed),pool=shuffle([...graph.words],rng);for(const start of pool){const q=[start],dist=new Map([[start,0]]);for(let p=0;p<q.length;p++){const d=dist.get(q[p]);if(d>=6)continue;for(const n of graph.neighbors(q[p]))if(!dist.has(n)){dist.set(n,d+1);q.push(n);}}const goals=q.filter(w=>dist.get(w)>=3&&dist.get(w)<=6);if(goals.length){const target=goals[Math.floor(rng()*goals.length)];return{id:'l'+seed,seed,start,target,path:[start],par:dist.get(target),hints:0,complete:false};}}throw Error('No connected ladder words available.');}
export function emptyExtras(){return {sudoku:{current:null,history:[]},ladder:{current:null,history:[]},semantic:emptySemantic()};}
export function validateExtras(data,ladderAllowed){const out=emptyExtras();if(!data)return out;
for(const type of ['sudoku','ladder']){const x=data[type];if(!x||!Array.isArray(x.history)||x.history.length>10000)throw Error('Invalid puzzle history.');for(const h of x.history)if(!h||typeof h.id!=='string'||h.id.length>80||typeof h.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(h.date)||!Number.isInteger(h.hints)||h.hints<0||h.hints>10000)throw Error('Invalid puzzle result.');out[type].history=x.history.map(h=>({id:h.id,date:h.date,hints:h.hints}));const g=x.current;if(!g)continue;if(typeof g.id!=='string'||g.id.length>80||!Number.isInteger(g.seed)||g.seed<0||g.seed>4294967295||!Number.isInteger(g.hints)||g.hints<0||g.hints>10000||typeof g.complete!=='boolean')throw Error('Invalid saved puzzle.');
if(type==='sudoku'){const board=a=>Array.isArray(a)&&a.length===81&&a.every(n=>Number.isInteger(n)&&n>=0&&n<=9),notes=a=>Array.isArray(a)&&a.length===81&&a.every(n=>Array.isArray(n)&&n.length<=9&&n.every(v=>Number.isInteger(v)&&v>=1&&v<=9));if(!['gentle','standard'].includes(g.level)||!board(g.givens)||!board(g.solution)||g.solution.includes(0)||sudokuConflicts(g.solution).size||!board(g.board)||!notes(g.notes)||!Array.isArray(g.undo)||g.undo.length>30||g.undo.some(u=>!board(u.board)||!notes(u.notes))||g.givens.some((v,i)=>v&&(g.solution[i]!==v||g.board[i]!==v))||!Number.isInteger(g.selected)||g.selected< -1||g.selected>80)throw Error('Invalid Sudoku backup.');const expected=createSudoku(g.seed,g.level);if(g.givens.some((n,i)=>n!==expected.givens[i])||g.solution.some((n,i)=>n!==expected.solution[i])||g.undo.some(u=>g.givens.some((n,i)=>n&&u.board[i]!==n)))throw Error('Sudoku clues do not match their seed.');if(g.complete!==g.board.every((n,i)=>n===g.solution[i]))throw Error('Invalid Sudoku completion.');out.sudoku.current={...g,noteMode:!!g.noteMode};}
else {if((g.draft!==undefined&&(typeof g.draft!=='string'||!/^[a-z]{0,4}$/.test(g.draft)))||!ladderAllowed.has(g.start)||!ladderAllowed.has(g.target)||!Array.isArray(g.path)||g.path.length<1||g.path.length>1000||g.path[0]!==g.start||g.path.some((w,i)=>!ladderAllowed.has(w)||(i>0&&!oneLetter(g.path[i-1],w)))||!Number.isInteger(g.par)||g.par<1||g.par>30||g.complete!==(g.path.at(-1)===g.target)||g.path.slice(0,-1).includes(g.target))throw Error('Invalid word ladder backup.');out.ladder.current=g;}}
out.semantic=validateSemantic(data.semantic);return out;}
